// FactoryPresets.swift — Phase 9. The 64 factory presets (two banks of 32),
// generated by tools/factory_presets.py into Resources/FactoryPresets.json and
// checked by DSPTests/test_presets (finite, gain-staged, distinct). The same
// file drives the web build, so the app, the AU and the browser load identical
// sounds. A preset stores only what differs from the defaults.
import Foundation

public struct FactoryPreset: Codable, Sendable, Identifiable, Hashable {
    public struct Cable: Codable, Sendable, Hashable { public var from: String; public var to: String; public var gain: Double }
    public var name: String
    public var bank: Int                 // 0 = Classic, 1 = Modular & Generative
    public var number: Int               // 0…31 within the bank
    public var category: String
    public var parameters: [String: Double]
    public var cables: [Cable]

    /// AUAudioUnitPreset.number: bank * 32 + number (factory presets are ≥ 0).
    public var presetNumber: Int { bank * 32 + number }
    public var id: Int { presetNumber }
}

public enum FactoryPresetLibrary {
    public struct File: Codable, Sendable { public var version: Int; public var banks: [String]; public var presets: [FactoryPreset] }

    public static let file: File = {
        guard let url = Bundle.module.url(forResource: "FactoryPresets", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let f = try? JSONDecoder().decode(File.self, from: data) else { return File(version: 0, banks: [], presets: []) }
        return f
    }()

    public static var banks: [String] { file.banks }
    public static var all: [FactoryPreset] { file.presets }
    public static func preset(number: Int) -> FactoryPreset? { all.first { $0.presetNumber == number } }

    /// Parameters that describe the player's setup rather than the sound
    /// (MIDI channel, zones, tempo sync, curves). Loading a preset keeps them.
    public static func isSetupParameter(_ identifier: String) -> Bool {
        let keep = ["global.sync", "global.receive", "global.velocityCurve", "global.programChange", "global.midi",
                    "global.mpe", "global.zone", "global.split", "global.tempo"]
        return keep.contains { identifier.hasPrefix($0) }
    }

    /// The complete state for a preset, keeping the current setup parameters,
    /// MIDI mappings and appearance. Clips are kept too: a preset is a sound.
    public static func state(for preset: FactoryPreset, keeping current: InstrumentState) -> InstrumentState {
        var s = current
        s.parameters = current.parameters.filter { isSetupParameter($0.key) }
        for (k, v) in preset.parameters where ParameterRegistry.spec(identifier: k) != nil && !isSetupParameter(k) { s.parameters[k] = v }
        var cables: [CableState] = []
        for (i, c) in preset.cables.enumerated() {
            let a = c.from.split(separator: "."), b = c.to.split(separator: ".")
            guard a.count == 2, b.count == 2 else { continue }
            cables.append(CableState(id: i, from: PortRef(module: String(a[0]), port: String(a[1])),
                                     to: PortRef(module: String(b[0]), port: String(b[1])), gain: c.gain))
        }
        s.patch = PatchState(cables: cables, layout: current.patch.layout)
        s.effects = EffectsState()        // factory presets use no impulse-response files
        s.preset = PresetReference(kind: .factory, name: preset.name, number: preset.presetNumber)
        return s
    }
}
